Roughly speaking, Codebreaker's strategy is to ask color queries having an expected answer of one. With constant probability, such a query contains exactly one color from $C^*$. Below is a precise formulation of this strategy.

\begin{algorithm2e} \While{$n' > 0$}{
    $k' \leftarrow \lceil |C_0|/n' \rceil$\;
    Let $C_{n'}$ be a random subset of $C$ with $|C_{n'}| = k'$\; 
    Ask the color query $C_{n'}$\;
    \If{$\mathrm{col}(C_{n'}) = 1$}{
       $C_0 \leftarrow C_0 \setminus C_{n'}$\;
       $n' \leftarrow n' - 1$\;       
       }
     }
\caption{Codebreaker's strategy}
\end{algorithm2e}

It remains to prove the estimate on the expected number of queries. To this aim, we first note that throughout a run of this strategy, $n'$ is the number of colors of $C^*$ left in $C_0$. Hence the event ``$\mathrm{col}(C_{n'}) = 1$'' occurs with probability
\begin{align*}
\frac{n' k' (|C_0| - n')  \ldots (|C_0| - n' - k' + 2)}{|C_0| \ldots (|C_0| - k' + 1)} 
&\ge \frac{(|C_0| - n') \ldots (|C_0| - n' - k' + 2)}{(|C_0|-1) \ldots (|C_0| - k' + 1)} \\
& \ge \bigg( \frac{|C_0| - n' - k' + 2}{|C_0| - k' + 1} \bigg)^{k'-1} = \bigg( 1 - \frac{n' - 1}{|C_0| - k' + 1} \bigg)^{k'-1}\\
& \ge \bigg( 1 - \frac{n' - 1}{|C_0| - (|C_0|/n')} \bigg)^{k'-1}\\
& \ge \bigg( 1 - \frac{|C_0| / (k'-1)}{|C_0| - (|C_0|/n')} \bigg)^{k'-1}\\
& \ge \bigg( 1 - \frac{1}{(k'-1)(1 - 1/n')} \bigg)^{k'-1},\\
\end{align*}
which is bounded from below by a constant (the later estimates assume $n' \ge 2$; for $n'=1$ the second term of the sequence of inequalities already is one).

In our proof we use the following properties of the entropy, which can easily be seen to hold for any two random variables $Z, Y$ over domains $D_Z, D_Y$.
\begin{itemize}
\item[(E1)] If $Z$ is determined by the outcome of $Y$, i.e., $Z = f(Y)$ for a deterministic function $f$, then we have

$H(Z) \le H(Y)$.


\item[(E2)] We have $H((Z, Y)) \le H(Z) + H(Y)$.


\end{itemize}

By our definitions, the sequence $Y:=(Y_1, Y_2, \dots, Y_s)$ determines $\tilde Z$, and hence by (E1) we have
\begin{equation} H(\tilde Z) \le H(Y) .
\end{equation}

We now derive an upper bound on $H(Y)$. For every $i$, $Y_i$ is binomially distributed with parameters $n$ and $1/k$. Therefore, its entropy is (see, e.g.,~\cite{jacquet1999entropy})
\begin{equation*}

H(Y_i) = \frac12 \log \left( 2\pi e \frac nk \Big(1 - \frac1k \Big) \right) + \frac12 + O \Big(\frac1n \Big) = O(\max\{\log(n/k), 1\}).
\end{equation*}
We thus obtain
\begin{equation} H(Y) \stackrel{\textup{(E2)}}\le \sum_{i=1}^{s} H(Y_i) = s H(Y_1) = s O(\max\{\log(n/k),1\}).
\end{equation}

Note that $\binom{2i}i 2^{-2i} \le 1/2$ for every $i \ge 1$, and $1-x \leq e^{-x}$ for all $x\in {\mathbb{R}}$. Hence,
\begin{align*}
p(d,k) & \le \left( 1 - \frac 2k \right)^d + \frac12 \sum_{j=1}^{d} \binom dj \left( \frac2k \right)^{j} \left( 1 - \frac2k \right)^{d-j} \\
& = 1 - \frac12 \left(1 - \left(1 - \frac2k \right)^d \right) \\
& \le \exp \left( - \frac12 \left(1 - e^{- \frac{2d}{k}} \right) \right).
\end{align*}








It follows that
\begin{equation} \ln \frac 1{p(d,k)} \ge \frac12 \left( 1 - e^{- \frac{2d}{k}} \right) .
\end{equation}

We show $n^{5d}(p(d,k))^N < 1$ for every $d \in [n]$, which clearly implies~\eqref{eq:non-adaptive-ultimate-goal}. In fact, we show the equivalent inequality
\begin{equation} \frac{N}{5d} \ln \frac{1}{p(d,k)} > \ln n.
\end{equation}
Using~\eqref{eq:non-adaptive-pdk} we obtain
\begin{equation} \frac{N}{5d} \ln \frac{1}{p(d,k)} \ge \frac{N}{10} \frac{1-e^{-\frac{2d}{k}}}{d}.
\end{equation}

Next we bound the exponent $\frac{n \log k}{k \log(n/k) \log n}$ in the previous expression. Note that the derivative of $\frac{n \log k}{k \log(n/k) \log n}$ with respect to $k$ is

\begin{equation} \frac{ n ( \log n - \ln(2) \log k \log (n/k))}{\ln(2) k^2 \log n \log^2(n/k)}.

\end{equation}

In the remainder of this proof we consider the case $k<cn$ and $d \ge \frac{n \log k}{\log(n/k) \log n}$. For such $d$ we establish the inequality $2^n k^{2n} (p(d,k))^N < n^{-2}$ which clearly implies~\eqref{eq:non-adaptive-ultimate-goal}. As done previously, we actually show the equivalent inequality
\begin{equation} N \log \frac1{p(d,k)} > 2 n \log k + n + 2 \log n.
\end{equation}
